// and "Fetch price tag". Blank is passed through unchanged so the existing `!= ''`
// presence gates keep behaving the same; a present-but-non-numeric value becomes "0",
// which matches no row instead of reaching the query as SQL.
const guardId = (v) => {
  const raw = String(v == null ? "" : v).trim();
  if (raw === "") return "";
  return /^[0-9]+$/.test(raw) ? raw : "0";
};
const plantIdSafe = guardId({{workflowparams:plant_id}});
const suppCustIdSafe = guardId({{workflowparams:supp_cust_id}});

return {
  document_type: document_type,
