const redisDataRaw = {{node:get_cache_node_ZqgOlvfi.data}};
const redisData = JSON.parse(redisDataRaw) || [];

// Get the workflow parameter data (which is an array)
const workflowItemData = {{workflowparams:item_data}} || [];

// Check if any item in redisData has use_price_tag = true
const hasUsePriceTag = redisData.some((item) => item.use_price_tag === true);

// Normalize numeric values to 4 decimal places before comparing, otherwise
// values like 5 vs 5.0 (or float noise like 5.00000001) read as different
const roundTo4 = (val) => {
  if (val === undefined || val === null || val === "") return null;
  const num = parseFloat(val);
  return isNaN(num) ? null : Math.round(num * 10000) / 10000;
};

// Check if unit_price is different between redisData and workflowItemData
let isPriceDifferent = false;
let isDiscountDifferent = false;
let isDiscountUomDifferent = false;
let isTaxRateDifferent = false;
let isTaxPercentDifferent = false;

if (redisData.length > 0 && workflowItemData.length > 0) {
  // For each item in redisData that has use_price_tag = true
  for (const redisItem of redisData) {
    const workflowItem = workflowItemData.find(
      (item) =>
        item.item_id === redisItem.item_id &&
        item.line_index === redisItem.line_index,
    );

    if (workflowItem) {
      // Check unit_price
      const redisPrice = roundTo4(redisItem?.unit_price);
      const workflowPrice = roundTo4(workflowItem?.unit_price);
      if (redisPrice !== workflowPrice && redisPrice !== 0) {
        isPriceDifferent = true;
      }

      // Check discount
      const redisDiscount = roundTo4(redisItem?.discount);
      const workflowDiscount = roundTo4(workflowItem?.discount);
      if (redisDiscount !== workflowDiscount) {
        isDiscountDifferent = true;
      }

      // Check discount_uom
      const redisDiscountUom = redisItem?.discount_uom || null;
      const workflowDiscountUom = workflowItem?.discount_uom || null;
      if (redisDiscountUom !== workflowDiscountUom) {
        isDiscountUomDifferent = true;
      }

      // Check tax_rate
      const redisTaxRate = roundTo4(redisItem?.tax_rate);
      const workflowTaxRate = roundTo4(workflowItem?.tax_rate);
      if (redisTaxRate !== workflowTaxRate) {
        isTaxRateDifferent = true;
      }

      // Check tax_percent
      const redisTaxPercent = roundTo4(redisItem?.tax_percent);
      const workflowTaxPercent = roundTo4(workflowItem?.tax_percent);
      if (redisTaxPercent !== workflowTaxPercent) {
        isTaxPercentDifferent = true;
      }
    }
  }
}

// Determine if overwrite is needed
let needOverwrite = "No";
if (
  hasUsePriceTag ||
  (isPriceDifferent ||
    isDiscountDifferent ||
    isDiscountUomDifferent ||
    isTaxRateDifferent ||
    isTaxPercentDifferent)
) {
  needOverwrite = "Yes";
}

return {
  data: redisData,
  needOverwrite: needOverwrite,
};
